class Solution {
public:
    void reorderList(ListNode* head) {
        ListNode* slow = head;
        ListNode* fast = head;
        while (fast->next && fast->next->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        ListNode* prev = nullptr;
        ListNode* cur = slow->next;
        slow->next = nullptr;
        while (cur) {
            ListNode* nxt = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nxt;
        }
        ListNode* a = head;
        ListNode* b = prev;
        while (b) {
            ListNode* an = a->next;
            ListNode* bn = b->next;
            a->next = b;
            b->next = an;
            a = an;
            b = bn;
        }
    }
};
